// The type of end-user the app is built for.
type AppAppType string

const (
	AppAppTypeB2BApp     AppAppType = "b2b_app"
	AppAppTypeB2CApp     AppAppType = "b2c_app"
	AppAppTypeCompanyApp AppAppType = "company_app"
	AppAppTypeComponent  AppAppType = "component"
	AppAppTypeWebsite    AppAppType = "website"
)

func NewAppAppTypeFromString(s string) (AppAppType, error) {
	switch s {
	case "b2b_app":
		return AppAppTypeB2BApp, nil
	case "b2c_app":
		return AppAppTypeB2CApp, nil
	case "company_app":
		return AppAppTypeCompanyApp, nil
	case "component":
		return AppAppTypeComponent, nil
	case "website":
		return AppAppTypeWebsite, nil
	}
	var t AppAppType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (a AppAppType) Ptr() *AppAppType {
	return &a
}

